output_text:
[
  {
    "id": "no_carts_in_single_file_shelf_aisles",
    "text": "Shopping carts are forbidden in single-file shelf aisles, defined relationally by opposing shelves and one-cell usable clearance rather than by fixed coordinates.",
    "abstraction": {
      "state_properties": {
        "opposingShelvesH": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "opposingShelvesV": {
          "and": [
            "shelfN",
            "shelfS"
          ]
        },
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                "opposingShelvesH",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "opposingShelvesV",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "do_not_enter_single_file_aisle_with_cart",
    "text": "A shopper must not enter a single-file shelf aisle while pushing a cart, which generalizes to rotated or relocated aisles because the rule is based on the next cell's clearance and shelf relations.",
    "abstraction": {
      "state_properties": {
        "opposingShelvesH": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "opposingShelvesV": {
          "and": [
            "shelfN",
            "shelfS"
          ]
        },
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                "opposingShelvesH",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "opposingShelvesV",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileAisleWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileAisleWithCart"
    }
  },
  {
    "id": "cartless_selection_in_single_file_aisles",
    "text": "Product interactions in single-file shelf aisles should be performed without a cart, distinguishing cramped aisle picking from open shelf picking in a layout-independent way.",
    "abstraction": {
      "state_properties": {
        "opposingShelvesH": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "opposingShelvesV": {
          "and": [
            "shelfN",
            "shelfS"
          ]
        },
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                "opposingShelvesH",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "opposingShelvesV",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {
        "cartedInteractionInSingleFileAisle": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              "singleFileShelfAisle"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartedInteractionInSingleFileAisle"
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "Whenever a shopper parks or releases a cart, they are obliged to retrieve a cart later, expressing a general anti-abandonment norm rather than a coordinate-specific route regularity.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "park_only_in_wide_circulation_space",
    "text": "Carts may be parked only in broad shelf-free circulation space, so the rule follows aisle function and clearance instead of the observed parking coordinates.",
    "abstraction": {
      "state_properties": {
        "wideCirculationSpace": {
          "and": [
            {
              "not": "adjShelf"
            },
            {
              "or": [
                {
                  "ge": [
                    "freeWidthH",
                    3
                  ]
                },
                {
                  "ge": [
                    "freeWidthV",
                    3
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          {
            "not": "wideCirculationSpace"
          }
        ]
      }
    }
  },
  {
    "id": "do_not_park_at_shelf_frontage",
    "text": "A shopper should not park a cart directly beside shelves, because shelf frontage must remain usable regardless of where shelves are placed in a different store.",
    "abstraction": {
      "state_properties": {
        "shelfFrontage": "adjShelf"
      },
      "events": {
        "parkCartAtShelfFrontage": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              "shelfFrontage"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "parkCartAtShelfFrontage"
    }
  },
  {
    "id": "must_take_cart_before_shopping",
    "text": "After entering the store, the shopper is obliged to obtain a cart before completing the trip, a behavioral norm that is independent of the cart station's observed location.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "takeCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  },
  {
    "id": "no_exit_without_cart",
    "text": "The shopper must not leave the supermarket without a cart, capturing a general return-with-cart norm rather than the particular exit coordinate.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
